// Package models defines the GORM database entities for the Go API service.
// This file declares the User model used for user registration, authentication, and email verification.
package models

import "time"

// User represents a registered user account persisted in PostgreSQL via GORM.
// This struct is migrated by database.RunDatabaseMigrations and serialized in API responses.
type User struct {
	// ID is generated by PostgreSQL using gen_random_uuid() when a new record is inserted.
	ID        string `gorm:"type:uuid;default:gen_random_uuid();primaryKey" json:"id"`
	Email     string `gorm:"uniqueIndex;not null" json:"email"`
	// Password stores the bcrypt-hashed password and is excluded from JSON serialization via json:"-".
	Password      string  `gorm:"not null" json:"-"`
	PasswordHash  *string `gorm:"-" json:"-"`
	Consented     bool    `gorm:"not null" json:"consented"`
	Verified      bool    `gorm:"default:false" json:"verified"`
	EmailVerified bool    `gorm:"-" json:"-"`
	// Nullable pointer fields allow PostgreSQL columns to store NULL until verification state is set or cleared.
	VerifiedAt                 *time.Time `json:"verified_at,omitempty"`
	// VerificationToken and its expiration timestamp are omitted from JSON responses to prevent leaking tokens.
	VerificationToken          *string    `gorm:"index" json:"-"`
	VerificationTokenExpiredAt *time.Time `json:"-"`
	CreatedAt                  time.Time  `json:"created_at"`
	UpdatedAt                  time.Time  `json:"updated_at"`
}
